class SmoothScrollAll{constructor(){this.targets=new Set();this.speed=.07;this.states=new Map();this.enabled=true;this.handleWheel=this.handleWheel.bind(this);this.loop=this.loop.bind(this);this.observeDom();this.initScrollables();this.loop()}initScrollables(){this.targets.forEach(el=>el.removeEventListener("wheel",this.handleWheel));this.targets.clear();this.states.clear();this.targets.add(window);[...document.querySelectorAll("*")].forEach(el=>{const s=getComputedStyle(el);if((s.overflowY==="auto"||s.overflowY==="scroll")&&el.scrollHeight>el.clientHeight)this.targets.add(el)});this.targets.forEach(el=>{const t=this.getScrollTop(el);this.states.set(el,{scrollTop:t,targetScrollTop:t});el.addEventListener("wheel",this.handleWheel,{passive:!1})})}observeDom(){new MutationObserver(()=>this.initScrollables()).observe(document.body,{childList:!0,subtree:!0})}getScrollTop(e){return e===window?window.pageYOffset||document.documentElement.scrollTop:e.scrollTop}setScrollTop(e,t){e===window?window.scrollTo(0,t):e.scrollTop=t}lerp(e,t,n){return e+(t-e)*n}handleWheel(e){if(!this.enabled)return;const t=e.currentTarget;e.preventDefault();const n=this.states.get(t);if(!n)return;n.targetScrollTop+=e.deltaY;const r=t===window?document.documentElement.scrollHeight-window.innerHeight:t.scrollHeight-t.clientHeight;n.targetScrollTop=Math.min(Math.max(0,n.targetScrollTop),r)}loop(){if(!this.enabled)return;this.targets.forEach(e=>{const t=this.states.get(e);if(!t)return;const n=t.scrollTop;t.scrollTop=this.lerp(t.scrollTop,t.targetScrollTop,this.speed);Math.abs(t.scrollTop-t.targetScrollTop)<.1&&(t.scrollTop=t.targetScrollTop);Math.abs(n-t.scrollTop)>.001&&this.setScrollTop(e,t.scrollTop)});this.frameId=requestAnimationFrame(this.loop)}}new SmoothScrollAll();
